    DB   $20,$66,$72,$65,$65,$6F,$6B,$0D,$0A,$00,$66,$72,$65,$65,$66,$61
    DB   $69,$6C,$3A,$0D,$09,$00,$42,$4F,$52,$44,$45,$52,$20,$32,$0D,$05
    DB   $00,$53,$54,$4F,$50,$0D,$08,$00,$66,$72,$65,$65,$6F,$6B,$3A,$0D
    DB   $0A,$00,$44,$20,$3D,$20,$35,$30,$31,$39,$32,$0D,$0A,$00,$50,$4F
    DB   $4B,$45,$20,$44,$2C,$33,$33,$0D,$0C,$00,$50,$4F,$4B,$45,$20,$44
