    DB   $2C,$32,$31,$30,$0D,$0D,$00,$50,$4F,$4B,$45,$20,$44,$2B,$33,$2C
    DB   $32,$30,$31,$0D,$0B,$00,$45,$20,$3D,$20,$55,$53,$52,$28,$44,$29
