    DB   $54,$4F,$20,$67,$6F,$73,$75,$62,$6F,$6B,$0D,$09,$00,$42,$4F,$52
    DB   $44,$45,$52,$20,$32,$0D,$05,$00,$53,$54,$4F,$50,$0D,$09,$00,$67
    DB   $6F,$73,$75,$62,$6F,$6B,$3A,$0D,$0B,$00,$50,$52,$49,$4E,$54,$20
    DB   $50,$49,$28,$29,$0D,$0E,$00,$50,$52,$49,$4E,$54,$20,$52,$41,$44
    DB   $28,$39,$30,$29,$0D,$0D,$00,$50,$52,$49,$4E,$54,$20,$44,$45,$47
    DB   $28,$31,$29,$0D,$08,$00,$50,$41,$55,$53,$45,$20,$35,$0D,$09,$00
